async function lifecycleUpgradeOpen(){
 if(window.electronAPI?.databaseMaintenance)return databaseMaintenanceOpen();
 const context=wfCommandContextStamp(),database=data;try{const c=lifecycleContext();if(c.actor?.role!=='admin'||!lifecycleCanRead(PlatformSchema.sections)||!lifecycleCanWrite(PlatformSchema.sections))throw Error('Обновление копии доступно администратору с полным доступом');if(!window.electronAPI?.inspectSchemaUpgrade||!window.electronAPI?.upgradeSchemaCopy)throw Error('Обновите программу: копирование нового формата недоступно');
 const info=await electronAPI.inspectSchemaUpgrade({});if(context!==wfCommandContextStamp()||database!==data)throw Error('База или права изменились');if(!info?.ok)throw Error(info?.error||'Не удалось проверить формат');
 wfShowDialog('Обновить копию базы','<form id="lifecycleUpgradeForm" class="wf-form"><p class="wf-wide wf-note">Будет создана отдельная копия формата '+htmlEsc(String(info.targetDescriptor?.schemaVersion||3))+'. Исходная база сохраняется. Рабочая база автоматически не переключается.</p><p class="wf-wide">Записей: '+info.counts.reduce((n,row)=>n+row.count,0)+' · формат '+htmlEsc(info.sourceFormat)+'</p><label class="wf-wide"><span>Новый каталог копии</span><input name="targetDir" required placeholder="Полный путь к новому каталогу"></label><label><span>Формат копии</span><select name="targetFormat"><option value="sqlite">SQLite</option></select></label><label class="wf-wide"><span><input type="checkbox" name="confirm"> Подтверждаю создание отдельной копии; исходная база останется прежней</span></label><p class="wf-wide" role="alert" data-upgrade-error></p><p class="wf-wide" role="status" data-upgrade-status></p><button type="submit" class="btn btn-primary">Создать копию</button></form>');const form=document.getElementById('lifecycleUpgradeForm');let pending=false;
 form.onsubmit=async event=>{event.preventDefault();if(pending)return;try{if(!form.isConnected||document.getElementById('lifecycleUpgradeForm')!==form||!form.closest('#wfModal.open')||database!==data||context!==wfCommandContextStamp())throw Error('Форма, база или права изменились');if(!form.elements.confirm.checked)throw Error('Подтвердите создание копии');const targetDir=form.elements.targetDir.value.trim();if(!targetDir)throw Error('Укажите новый каталог');pending=true;const unlock=wfLockCommandForm(form);try{const result=await electronAPI.upgradeSchemaCopy({targetDir,targetFormat:form.elements.targetFormat.value,expectedSourceFingerprint:info.sourceFingerprint});if(database!==data||context!==wfCommandContextStamp())throw Error('База или права изменились. Проверьте результат копирования отдельно.');if(!result?.ok)throw Error(result?.error||result?.message||'Копия не подтверждена. Проверьте целевой каталог перед повтором.');form.querySelector('[data-upgrade-status]').textContent='Копия создана: '+result.targetDir+'. Откройте её вручную после проверки. Текущая база не переключена.';form.querySelector('button[type=submit]').hidden=true;}finally{unlock();}}catch(error){form.querySelector('[data-upgrade-error]').textContent=error.message;}finally{pending=false;}};
 }catch(error){showToast(error.message);}
}

async function databaseMaintenanceOpen(options={}){
 const database=data,context=wfCommandContextStamp(),openingModal=document.getElementById('wfModal'),openingContent=openingModal?.innerHTML,openingClass=openingModal?.className;let form=null,pending=false,review=null,reviewStamp=null,backup=null,resumeOnly=false;
 const guard=()=>{if(data!==database||wfCommandContextStamp()!==context||form&&(!form.isConnected||document.getElementById('databaseMaintenanceForm')!==form||!form.closest('#wfModal.open'))||!form&&(document.getElementById('wfModal')!==openingModal||openingModal?.innerHTML!==openingContent||openingModal?.className!==openingClass))throw Error('База, права или окно изменились. Откройте проверку заново.');};
 const rpc=async payload=>{guard();const result=await electronAPI.databaseMaintenance(payload);guard();if(!result?.ok)throw Error(result?.error||'Действие с базой не подтверждено');return result;};
 try{
  if(lifecycleContext().actor?.role!=='admin'||!window.electronAPI?.databaseMaintenance)throw Error('Действия с базой доступны администратору на основном компьютере');
  if(options.backup){backup=await electronAPI.chooseMaintenanceBackup();guard();if(backup?.canceled)return;if(!backup?.ok)throw Error(backup?.error||'Пакет не проверен');}
  const profiles=await rpc({action:'profiles'}),saved=await rpc({action:'list'}),info=backup||await rpc({action:'inspect'});
  const identityLabel=identity=>identity?identity.uuid+' · поколение '+identity.generation:'Идентичность неизвестна';
  wfShowDialog(backup?'Восстановление отдельной базы':'Копии и перенос базы','<form id="databaseMaintenanceForm" class="wf-form"><p class="wf-wide wf-note">Исходная база сохраняется. Проверенная копия создаётся в новом каталоге; переключение профиля выполняется отдельно.</p><p class="wf-wide" data-maintenance-source>'+htmlEsc(backup?'Пакет: '+backup.name:'Исходная база · '+info.sourceFormat)+'<br>'+htmlEsc(identityLabel(info.sourceIdentity))+'</p><label class="wf-wide"><span>Действие</span><select name="mode"><option value="clone">Самостоятельная копия — новая идентичность</option>'+(backup?'<option value="restoreContinuation">Продолжить прежнюю базу — следующее поколение</option>':'<option value="relocate">Перенести — сохранить идентичность и поколение</option>')+'</select></label>'+(backup?'<label class="wf-wide"><span>Текущий профиль для продолжения</span><select name="head">'+profiles.profiles.map((row,index)=>'<option value="'+index+'"'+(row.state==='known'?'':' disabled')+'>'+htmlEsc(row.name+' · '+identityLabel(row.identity)+(row.state==='known'?'':' · метаданные не подтверждены'))+'</option>').join('')+'</select></label>':'')+'<label class="wf-wide"><span>Новый каталог</span><input name="targetDir" required placeholder="Полный путь к новому каталогу"></label><label><span>Формат</span><select name="targetFormat"><option value="json">JSON</option><option value="sqlite">SQLite</option></select></label><label class="wf-wide"><span>Основание</span><input name="reason" required maxlength="2000" placeholder="Для чего создаётся копия или восстановление"></label><button type="button" class="btn btn-ghost" data-maintenance-preview>Проверить план</button><div class="wf-wide" data-maintenance-review role="status"></div><label class="wf-wide"><span><input type="checkbox" name="confirm"> Проверил назначение, режим и идентичность копии</span></label><button type="button" class="btn btn-primary" data-maintenance-apply disabled>Создать по проверенному плану</button><p class="wf-wide" role="alert" data-maintenance-error></p><p class="wf-wide" role="status" data-maintenance-result></p>'+(saved.reviews.length?'<label class="wf-wide"><span>Сохранённые планы, включая прерванные</span><select name="savedReview">'+saved.reviews.map((row,index)=>'<option value="'+index+'">'+htmlEsc(row.at+' · '+row.targetDir)+'</option>').join('')+'</select></label><button type="button" class="btn btn-ghost" data-maintenance-resume>Показать сохранённый план</button>':'')+'<button type="button" class="btn btn-ghost wf-wide" data-maintenance-profiles>Проверить известные профили</button><p class="wf-wide" data-maintenance-profiles-result></p></form>');
  form=document.getElementById('databaseMaintenanceForm');form.onsubmit=event=>event.preventDefault();form.elements.targetFormat.value='sqlite';
  const applyButton=form.querySelector('[data-maintenance-apply]'),errorBox=form.querySelector('[data-maintenance-error]'),reviewBox=form.querySelector('[data-maintenance-review]');
  const input=()=>({mode:form.elements.mode.value,targetDir:form.elements.targetDir.value.trim(),targetFormat:form.elements.targetFormat.value,reason:form.elements.reason.value.trim(),...(backup?{backupId:backup.backupId,...(form.elements.mode.value==='restoreContinuation'?{headProfileId:profiles.profiles[Number(form.elements.head.value)]?.id}:{})}:{})});
  const invalidate=()=>{review=null;reviewStamp=null;applyButton.disabled=true;form.elements.confirm.checked=false;reviewBox.textContent='Параметры изменились. Проверьте план перед созданием.';};
  for(const element of form.querySelectorAll('input:not([name="confirm"]),select:not([name="savedReview"])')){element.addEventListener('input',invalidate);element.addEventListener('change',invalidate);}
  function showReview(value){review=value;reviewStamp=JSON.stringify(input());form.elements.confirm.checked=false;reviewBox.textContent=({clone:'Самостоятельная копия',relocate:'Перенос',restoreContinuation:'Продолжение после восстановления'})[value.mode]+'\nИсходник: '+(value.sourceLabel||'проверенный исходник')+'\nИсходная база: '+identityLabel(value.sourceIdentity)+'\nКаталог: '+value.targetDir+'\nИтоговая база: '+identityLabel(value.targetIdentity)+(value.predecessor?'\nПродолжает: '+identityLabel(value.predecessor.identity):'')+'\n'+(value.warnings||[]).map(row=>row.message).join('\n');reviewBox.style.whiteSpace='pre-wrap';applyButton.disabled=false;}
  async function run(action){if(pending)return;let unlock;try{guard();pending=true;unlock=wfLockCommandForm(form);errorBox.textContent='';await action();}catch(error){errorBox.textContent=error.message;}finally{pending=false;unlock?.();if(form.isConnected){applyButton.disabled=!review;if(resumeOnly){for(const field of form.querySelectorAll('input:not([name="confirm"]),select:not([name="savedReview"])'))field.disabled=true;form.querySelector('[data-maintenance-preview]').disabled=true;}}}}
  form.querySelector('[data-maintenance-preview]').onclick=()=>run(async()=>showReview(await rpc({action:'preview',...input()})));
  form.querySelector('[data-maintenance-resume]')?.addEventListener('click',()=>run(async()=>{const value=saved.reviews[Number(form.elements.savedReview.value)];if(!value)throw Error('План не выбран');if(!Array.from(form.elements.mode.options).some(option=>option.value===value.mode)){const option=document.createElement('option');option.value=value.mode;option.textContent='Продолжить прежнюю базу — следующее поколение';form.elements.mode.append(option);}form.elements.mode.value=value.mode;form.elements.targetDir.value=value.targetDir;form.elements.reason.value=value.reason;form.elements.targetFormat.value=value.targetFormat;resumeOnly=true;form.querySelector('[data-maintenance-source]').textContent='Сохранённый план: '+(value.sourceLabel||'проверенный исходник')+' · '+identityLabel(value.sourceIdentity)+'. Исходник и режим закреплены; для других параметров откройте новое действие.';showReview(value);}));
  applyButton.onclick=()=>run(async()=>{if(!review||reviewStamp!==JSON.stringify(input()))throw Error('Проверьте текущие параметры заново');if(!form.elements.confirm.checked)throw Error('Подтвердите проверенный план');const result=await rpc({action:'apply',reviewId:review.reviewId,reviewFingerprint:review.reviewFingerprint});form.querySelector('[data-maintenance-result]').textContent='Копия подтверждена: '+result.targetDir+'. Текущий профиль не переключён.';review=null;applyButton.disabled=true;});
  form.querySelector('[data-maintenance-profiles]').onclick=()=>run(async()=>{const result=await rpc({action:'profiles'}),profileBox=form.querySelector('[data-maintenance-profiles-result]');profileBox.textContent=result.profiles.map(row=>row.name+' · '+row.state+'\n'+(row.dataDir||'')+'\n'+identityLabel(row.identity)).join('\n\n')+'\n\n'+result.groups.map(row=>({sameLocation:'Несколько профилей указывают в одну папку',duplicateIdentity:'Одна идентичность в разных папках',multipleGenerations:'Известны разные поколения одной базы'})[row.kind]).join('\n');profileBox.style.whiteSpace='pre-wrap';});
 }catch(error){showToast(error.message);}
}
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&lifecycleSession?.pending&&document.getElementById('wfModal')?.classList.contains('open')){event.preventDefault();event.stopImmediatePropagation();}},true);
